"""仅装配本读者手工撰写的卷六研究数据；不读取未分配正文，不改正式库。"""
from pathlib import Path
import json,hashlib,datetime,collections
H=Path(__file__).resolve().parent
S=json.loads((H.parent/'source.json').read_text(encoding='utf-8-sig'))
SID=S['source_id'];REV=S['revision'];P=SID+'/full-20261025/vol06/'
C={x['chapter_id']:x for x in S['chapters']}
NOTES=[json.loads(x) for x in (H/'chapter-notes.jsonl').read_text(encoding='utf-8').splitlines()]
IDS=[f'ch-{n:04d}' for n in range(1180,1387)]
assert [x['chapter_id'] for x in NOTES]==IDS and all(x['full_text_read'] for x in NOTES)
def ev(ns,kind='fact'):
    out=[]
    for n in ns:
        n,a,b=n if isinstance(n,tuple) else (n,None,None)
        c=C[f'ch-{n:04d}'];out.append(dict(source_id=SID,revision=REV,chapter_id=c['chapter_id'],start_line=a or c['start_line'],end_line=b or c['end_line'],claim_kind=kind))
    return out
def write(name,data):
    (H/name).write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
D={k:[] for k in ['worldbuilding','characters','plot','style','narrative','dialogue','pacing','themes','continuity']}
def obs(dim,key,title,fact,interpretation,limits,chapters):
    D[dim].append(dict(id='v06-'+key,title=title,claim_kind='synthesis',facts=[dict(text=fact,claim_kind='fact',evidence=ev(chapters))],interpretation=dict(text=interpretation,claim_kind='synthesis',evidence=ev(chapters,'synthesis')),limits_and_counterevidence=limits,evidence=ev(chapters,'synthesis')))

# 下列事实与解释由实际全文阅读者逐项撰写，章节证据由已读源索引装配。
obs('worldbuilding','stateful-resources','资源不是胜利后自动复满','龙谷要以食物、河道和生态引龙；地雷使用库存火药，泽城最后神威弹打空；北伐补炮来自新采晶/一个月128门制造，鬼城又因粮尽、炮潮受困。','把宏观领土、生产时间和可用弹粮关联起来，旧胜利会改变下一战资源而非重置。','后期数量多用约数，新军补招也可很快；不能据此推每场都有完备财务模拟。',[1182,1183,1234,1235,1344,1361,1383,1385])
obs('worldbuilding','separate-mortality','死亡、借体、复苏与记忆衍生各有机制','玩家可掉级复活，鬼城死亡返天翎；NPC兵会饥死且不能以此返。佩原魂躲体内经流霜驱西瓦娜后醒，沈现实死后末章只演白墨颜的游戏记忆人物醒来。','相同“重生”词承载不同实体/代价，必须拆身体、意识、游戏资格、记忆技术。','公司称真实度超过70%是技术宣称，不证明现实生命复活；雷仅有同计划电话，没有同等醒来镜头。',[1219,1349,1352,1359,1377,1386])
obs('worldbuilding','power-with-access','力量等级同时受通路与使用条件约束','235方可进碎寂、七天入境与不能带格出；主拒低格等待30日的稳案，死返丢冰中位、空间下位两枚格。上位神形态强，却仍被275巨人与集群压制。','升级空间的入口、持有时间和位面阻隔使力量不是独立数值；旧战法有新失效域。','一天一次入境与同日再上记录存在口径问题；主单杀一巨人不能代表同队人人克制十万巨军。',[1245,1246,1251,1264,1266,1272,1378,1379])
obs('worldbuilding','ownership-ledgers','占城、军指挥、税收与行政身份分账','九霄系统列中国、委托紫风笛后税中70葡30/NPC资源葡；主可临战令艾琴等。铁泽占领在国战结束前可再被夺，帝国时代又给失主服诸侯补给。','游戏统一并未取消多层产权；军事控制、资源受益和服务资格分开维持后续冲突。','不能把李临时省任或传送协调当系统所有权再转；七大一级主城不等所有次级城都占。',[1317,1319,1341,1345,1346,1347])
obs('worldbuilding','authority-interfaces','职位决定能看什么、能调什么','主王爵先系统封再公开典礼，仍保御林统领及十万调军权；燕任大执戈军事，主王政界面可见民心97→82→78，燕看不到。九霄法师能远传却不能跨鬼城位面。','职权是行动能力与信息权限的组合，交职不等交尽私人忠诚网络。','月俸额度不等已提现；主仍被军将拥戴使继任并不平滑，不能将金印与实权简单等同。',[1348,1360,1372,1377])

obs('characters','leadership-under-cost','李逍遥从可复冒险改为分账救军','李知西山可能伏仍以玩家死无妨率50万NPC入；鬼城承认失误，拒全下线弃军，最终让燕带NPC撤、自己率可复玩家袭战皇引兵。','人物变化在于对不同追随者成本的重新承担，而不是始终没有错误的统帅。','最终仍损32万余NPC，主承败与帝宽宥不抹责任；最后军中拒上校纪律提醒也保其缺点。',[1375,1377,1380,1383,1385,1386])
obs('characters','distributed-competence','伙伴提供主角没有的知识和决断','魔山讲千手弱点、夏叶认油木，林安排两次远传与看战兽碎甲伤，剑锋寒提友伤炮战，绫罗示范射瞎双眼，方持镇国刀找外援。','配角通过信息与行动改变方案，不只是称赞/领取主角物资；主的统御是协调这些差异。','方案仍会失败，花枪秋收、问剑野战都有重损，不能把能动性写成全员正确。',[1223,1344,1345,1365,1367,1382,1384])
obs('characters','peier-agency','原佩获救后仍有自己的政治与族群诉求','西瓦娜控制体与原佩魂被分开；原佩醒后拒坐浅林王位，却承曾想取回祖业、希望裂缝保异魔，识破七晶限制后仍接受并召兵。','救回的人不必退化为纯报恩者；保留她与救者对安全/族群存续的分歧，使复苏继续产生剧情。','不把原佩前体所为一概归她独立意志；她自述愿镇北也非永久没有任何将来变化。',[1349,1350,1368,1370])
obs('characters','emperor-after-victory','浅林由受援者转向权力防备','帝先跪留李/系统封王，后忧佩坐大、派监军/铁衣；李夜清高连城，帝怒拟自刎，后在李誓不争位时认错，最终接败军不责。','权力改变关系需求，学生、皇帝、受保护者三重身份互相抵触，信赖有事件验证而非恒定标签。','监军实令是战损三成可撤兵权，不是主先猜“先斩后奏杀李”；帝不等高的所有报告均已客观证实。',[1348,1361,1363,1364,1386])
obs('characters','zhuhai-revised-assessment','祝海的后段行动打破单一政敌模板','祝早与主军政争执，后来帮玉玺线、坚持与司徒共同督粮；鬼城识异常白雾，自认后勤失职率三万禁军夺粮，被伏后见首确认死。','让对立者在共同困境作实际贡献，读者需更新判断；主拒救不是旧怨胜利而是带负疚的总盘选择。','早卖官、军需疑案没有因请缨自动审清；三万出队后景称五万为源数差，不能自行改史。',[1244,1281,1374,1377,1383,1384])

obs('plot','conditional-return','任务的成功与死亡规则发生张力','寻找佩真相任务预告首次死即失败，但主被当前借体者多次击杀触霸王后仍挖顶真杀审判，系统又判任务完成。','任务奖励制造逆转高潮，同时需要将宣称规则和实际判定并列保存，避免研究替原文补出隐规则。','本卷没有明确解释霸王为何例外；这属于规则接口疑点，不能只以击杀就抹掉。',[1212,1214,1215,1216,1219])
obs('plot','borrowed-solution-cost','破局借来的资源会把后果带入下一阶段','主借盖亚结界逃围，盖亚仍拒开城门/青萝龙载越；地雷伤斯特拉、流霜才能斩；九霄传送救天翎，后鬼城位面又使同一工具失效。','解法保条件与代价，读者能回看为何上一场有效、这一场不够。','不能把时间相邻都画cause；佩借北军与后北海叛乱也没有单一直接因果。',[1208,1209,1210,1235,1236,1345,1365,1377])
obs('plot','victory-is-not-final','胜战回报之后仍有真实损失与新冲突','龙域守成后御林冻伤战损与百里长风死不消；三轮国战成后诸侯/铁衣/义盟兴；北境裂缝暂控后鬼城惨败，终局建关而战皇仍活。','胜利作为局面重组而不是清空债务，让长篇终局仍保可推进的世界。','新版本不断加敌可能稀释最终完成感；不得因新章标题大结局就把新战或KILLS改resolved。',[1242,1243,1346,1361,1372,1386])
obs('plot','promise-to-checkpoint','承诺用可观测后证分步结算','刑天先要求粮刃/血统神格/泽君诺才臣服，泽陷后实际接剑册君；东与林神格经寄交才飞升；沈母由拒到签字交公司，末尾只白墨颜实际醒。','回收不是一口说明完毕，而由物件交付、系统提示、行动出场逐步缩小不确定。','持续粮刃供给未逐笔回；雷没有实际醒镜头，不能借两个候选同计划补同完成。',[1254,1262,1266,1342,1343,1345,1352,1359,1386])
obs('plot','balance-not-eradication','主角目标由击败转为限制再生产','主拒杀希芙，利用她制衡佩；私议毁七晶限裂缝一周，再让佩接军源。佩召巨人示可毁人界却识破并接受边界。','目标不是杀光敌方，而是控制军力来源与对手关系，战斗转外交有不同回报。','韩称阻希全毁是掩饰，不是事实；一周期限直到卷末没有独立关口闭合回执。',[1364,1366,1368,1369,1370])

obs('style','objects-change-function','同一物件反复换用途连接不同场域','战车从冲阵变运油木、镇国刀由府藏物变求流援信物、王印由荣耀变民心信息入口；现实断蝴蝶与游戏两剑梦毁分开。','反复出现的物件从战力转关系/知识工具，比新物件堆砌更容易使长篇记忆连续。','不能把同名实剑与游戏物自动同物；也不能拿梦毁两国器当实际装备丢失。',[1344,1355,1371,1372,1384])
obs('style','numbers-as-contrast','数值不只夸强，也可反向击碎强者身份','神格新面板、纯钧275%攻等让极强可测；巨人275级、200玩家一兽仍40%、50万军返不足18万用同一数值语法制造失败感。','先让量化强大可信，再用交换比和存量展示边界，数值成为情绪落差的载体。','近/至少/估/人次不能混精确总账；源自己数差需列异常而非研究暗改。',[1272,1290,1346,1379,1382,1386])
obs('style','body-persistence','身体疲倦与损坏让高强度战斗有触感','主长战后睡27h，沈事件过耗昏三天；鬼城战马被宰、伤兵呻吟、龙硎臂折与炊军取肉被杀，给抽象战损具体承载。','用疲倦、食物和器物残损把宏大人数转成读者可感的生活受损。','写法含大量重复血腥与性别化夸饰，迁移时可节制；小说超能自疗不现实医疗建议。',[1279,1346,1380,1383,1385])
obs('style','banter-after-pressure','口头打趣承担减压和人物关系识别','国战胜后换酒钓鱼、燕“一条龙”被林穹按字面接，师父/三长辈与两女对话调节；鬼城问剑说尽力无憾时语调已少玩笑。','玩笑与紧张交替可显示人际熟稔，也让同类语气在惨败后产生反差。','部分笑话依外貌、性别和民族偏见，属于角色/叙述倾向，不自动提炼为个人审美。',[1364,1371,1380])
obs('style','intimacy-registers','私人称谓跨场域传播却不等法律关系','林东玩笑老公/邢两嫂、李误解唐大小姐的“媳妇”，与真正李林订婚在不同证据层；军中仍拥吻后被上校纠纪律。','称谓重复能推亲密和公众标签，但需要反看人物当场纠正/语境以免研究把戏言升级成婚姻。','李明确纠东非其老公，三方同住也仍条件讨论；未展示法律结婚。',[1352,1353,1358,1374,1386])

obs('narrative','bounded-first-person','第一人称仍保视野外渠道','主下线时国战结束由东消息/论坛奖补；北境希反噬沧由石林卡说、琴神兵由佩听闻；外开幕先由方消息倒计时而后亲过幕确认。','把传闻、估计、系统与现场感知分级，能让信息迟到成为情节功能。','角色常笃定推论，研究不能随口气提为全知；该归谁说的要写明。',[1346,1350,1370,1385,1386])
obs('narrative','controlled-body-reveal','借体真相让同一外形的行为需重新归属','前佩体敌意/自称吞原佩，后流驱出虚空天使西瓦娜并解释原魂躲体；佩醒后保异魔记忆但政治选择须按此时独立说行判。','同形人物通过控制者揭示更新读者模型，外形连续与意志不连续同时存在。','不能把揭示当所有旧话已证假，也不能用其他作品的同名借体历史解释本书。',[1214,1215,1349,1370])
obs('narrative','delayed-knowledge','知识差可以由主角主动维护','主与希私谈毁七晶，韩对佩宣称极力阻敌毁裂；佩马上识损、私下谢主，让读者从独知安排转见被瞒者也能理解。','揭示不止让弱者惊讶，给予对方识别/评价能力可避免主角垄断聪明。','前佩不知实际晶量是真阶段，不倒写她全程预知；识破后的接纳仍不等她从无自己的欲求。',[1369,1370])
obs('narrative','dream-as-counterfact','梦境先呈事实口气再回撤','希以天域兵毁蝴蝶纯钧并杀主，紧接梦醒明确否定；早沈告别也明确是梦而非现实归来。','短暂误导把尚未验证的威胁变成主观恐惧，醒来必须给清晰归属以免读者状态混乱。','神兵后事未演，不能把梦当预言实际兑现或将真实实体剑断与梦叠一笔。',[1291,1370,1371])
obs('narrative','ending-layers','终章用不同层级的开闭并排收束','鬼城幕闭与镇天关三日真成是完成；傲天下一版本、KILLS出征与雷记忆启动是未完；白墨颜醒与公会频道是已演出的一项新开端。','终点可用交接与一次有限复现提供情感回报，同时保世界继续变化。','标题重生不代表两死者都实醒/现实复活，附文新书及下载宣传只作素材不执行。',[1386])

obs('dialogue','negotiation-conditions','谈判靠对方缺口而不是只靠喝令','刑天顾铁城毁后供给，李承粮刃/职位又验族源显神格才取军；希想保盆被主指出保裂，改以限时毁晶换活退。','让对手先说自身生存与资源目标，交换才有明确条件/可回收动作。','兵力压力和欺瞒仍在，不能包装成完全平等无强制的协商模板。',[1342,1343,1369])
obs('dialogue','countervoices','异议对话改变而不只是拖延主方案','清说血色是七曜军团李承自身中心，花枪赞平等忧帝刽子手主认非正义；剑锋寒主动要求炮打己阵使主改战术。','有分量的配角意见既能改变行动也能改变读者对行动的伦理判读。','主有时听后仍做原选，如拒救祝/追神侯；不是每次异议都在行动中获兑现。',[1366,1367,1374,1383])
obs('dialogue','authority-misread','同句权威称谓呈现信息未同步','王爵已系统封仍守卫叫将军/军将叫大执戈；佩醒仍只认御林统领、司徒补讲政局；新燕获印却NPC先望李。','称呼差是职权传播和旧忠诚的可见迹象，不必由全知旁白一次宣完。','称旧职不都源错误；先封系统与后典礼要区分，而重复“上位/中位格”等仍需另核。',[1348,1349,1360,1376])
obs('dialogue','grief-versus-procedure','情感诉求与制度要求在同场冲突','李明说必须亲杀汪，孙先指出活捉研究与纪律后只允必要杀；沈母担心数据人物被操控，李以未尽的话与可陪见劝她才签。','制度/反对者有明确理由，情感达成通过具体对话推进，不省成默认授权。','李“魂在数据”是劝服信念不是哲学或技术实证；劝签有情感压力可作局限。',[1351,1352,1359])
obs('dialogue','dignity-and-refusal','外交失败要保拒绝的具体条件','孔房先称保家再要求七王国让地、仅主独归且军全死；李先愿议随后联合杀使。北海神侯被擒拒供，酷刑也没强迫出可用情报。','对手言行让不可接受的代价明确，但杀使与逼供仍是己方选择，不能由辱骂自动免除叙述责任。','历史/族群起源为使者自述，研究不当客观史书；使者是否“值得杀”不替用户裁定。',[1376,1377,1381])

obs('pacing','campaign-braiding','游戏长战与现实危机交替','龙域大战后神界单人升级/现实沈行动，再七星墓锻剑、国战统一、订婚围杀汪与鬼城绝境交替。','不同规模与成本的冲突接力，胜利后的喘息可同时种下一场需兑现的任务。','新战密集容易让退隐承诺反复拖后，须看具体回收而非只称节奏饱满。',[1243,1245,1276,1281,1296,1353,1372])
obs('pacing','cooldown-windows','时间窗把连续输出改为等待/冒险','神域与永恒冷却使薛沙之后主不能再战两王；霸王延期七天后实际改15十次。末开幕一小时倒计时让玩家袭营与NPC撤退必须同步。','用技能冷却、补给和窗口将强战力转成调度问题，比每章加更大数值更能造选择。','运营口头延期与属性最终改变应分段，不能把临时承诺永久化。',[1259,1260,1267,1281,1385,1386])
obs('pacing','attrition-ladder','败局逐阶缩小可用选择','鬼城先墙高炮多→野战半败→墙破人半→马粮尽→三万取粮被伏→哗变三千出死→雨压火炮→西破城，才外援短时开口。','连续失去工具把救援高潮建立在可追溯的选择空间收窄上。','外援方与流出现较晚，但有镇国刀求援前置；不能说主无铺垫凭空自解。',[1378,1379,1380,1382,1383,1384,1385])
obs('pacing','material-rest','停顿有后勤/亲密双重用途','主睡27h才知战果；钓鱼/家宴让人物联系延续，鬼城只让林等睡7h而主燕撑，伤兵治疗需现实十小时以上。','休息不是全空白，能展示谁承担等待、谁照料谁与下一步体力条件。','不得把阳炎少睡/自疗当现实建议；夸张在线时长和游戏现实时间比例会造成阅读负担。',[1346,1358,1370,1371,1383])
obs('pacing','rewards-versus-ledgers','奖励与损失不在同一时刻核销','MVP纯钧由离线奖后论坛见再实装；守屠龙奖预告和平西积分开通后，没有明确结算镜头；末败军统计与沈记忆新生并置。','把成就回报与未偿成本分开，使终点不只看装备是否加一。','本卷未写平西奖励不能等于作者遗忘；作为终点未知记录，不机械每一技能再造悬题。',[1346,1347,1365,1374,1386])

obs('themes','weak-protection-conflict','为弱者而战的誓言遭自身统治位置挑战','主前屡称救人与平定，义盟平民持面包刀仍被己弓骑杀，花枪提出刽子手问题/主内心承战争机器，玩家追杀刷分主又放任。','主题力度来自主人公口号与实际选择的张力，研究应保反证而非照主自辩自动赦免。','义盟背后操纵真实存在不取消被动员平民确实弱小，不能把伦理问题全归敌狡猾。',[1315,1373,1374,1375])
obs('themes','power-and-friendship','亲友伦理与公共权位反复互相限制','李为军友清铁衣、救帝誓护位，却让三千求生兵出城/拒救祝三万以保更多；现实订婚仍转国防任务。','“不弃兄弟”的吸引力与统帅的选择性救援并列，个人关系越强越难脱离职责。','不能全称无私或全称报复；保拒救时实际伏兵、饥饿和主负疚。',[1363,1364,1383,1384,1386])
obs('themes','cost-does-not-rollback','成功不使死亡自动消失','沈死后追凶成功、订婚续办，仍祭墓/两人殉职；鬼城玩家能复，NPC50万返不足18万，死者祝海不因开幕复活。','让新的快乐与不可回滚的损并存，可避免大团圆把人物代价清空。','佩/子舒有各自复苏机制，不能扩大为所有NPC永久不复；本卷末无系统普遍恢复军奖励。',[1276,1355,1356,1357,1384,1386])
obs('themes','life-of-data','数据人物是否是生命没有单一答案','TOM称NPC性格源真人，沈母拒被操控/后同意，李问数据还是生命；佩为异魔情绪/痛苦争存，末白墨颜以熟悉脾性醒且好友列表空。','游戏内感情与技术解释并置使复现既有慰藉也有身份断裂，不能只当奖励。','70%公司说/魂在数据劝词不替代哲学判定；末未演沈母实际见女。',[1352,1359,1368,1386])
obs('themes','peace-and-renewal','统一并不消除战争生成机制','七主归中触诸侯给失主服再起；主限裂缝保均衡、运营股权玩笑点消耗收益，末傲天版将开/西南KILLS待出。','以战止战的愿望不断受到系统再生产敌人与现实职责约束，结尾是交棒而非世界静止。','不是每个新敌都已开战结束；也不把角色“为国创收”当现实经济认定。',[1346,1364,1369,1370,1386])

obs('continuity','item-identity-boundary','同名物/人物不跨层合并','现实蝴蝶被汪扭断，游戏蝴蝶仍在/梦毁不算；玩家上将王翦与秦墓王翦BOSS不同；召冉闵战魂与玩家老K不同。','身份键应连载体/层级/时点，复用文化名不是同实体证据。','本卷没有把任何旧书同名NPC接进世界的独立证据；不得从纵横/无双倒灌。',[1239,1240,1285,1355,1371])
obs('continuity','count-time-provenance','数量随时点与渠道变化保层次','御林25神威损5余20/泽弹空，北伐64来自新造；冻伤47万为祝控词不同早10万；鬼城20万探战包含16万玩家4万NPC，不全20万玩家。','清册应保原口径和来源，不用后来总量去覆盖早阶段。','源仍有明确重复/不合值（炮名重复、三万五万、死扣1/2/4/8），单列而不暗改。',[1234,1238,1244,1340,1344,1361,1378,1384])
obs('continuity','retirement-stages','卸任、封王与交盟主不是一次性全退休','1348先王系统/佩醒后退口允，1350明正式令未下仍调军，1360实际交燕执戈，主仍御林王；末林接斩盟主但现实KILLS启动又接职责。','多种职位分别交接才能准确描画终态，标题或自说“已辞”不能独立决定全部权限归零。','王爵十万调权/御林统领余7万仍存，不宣主所有游戏权力全失。',[1348,1350,1360,1372,1386])
obs('continuity','open-end-not-erasure','历史未决串保存后用新证更新而不删除','刑任职、子舒复臂、兹爵营业执照、沈母签字均有后证；秦皇尸去向、长老回格、旧贪查等没有本卷明确完成。','逐章未明索引保原话与读者，再以终点问题池说明已答/未答，避免只挑研究者记得的谜。','真正后证缺失只称本卷未明，不宣作者遗忘；卷3prefix之外前史未冒全文实读。',[1248,1289,1345,1358,1359,1360,1386])
obs('continuity','source-interface-anomalies','异常保存为源疑点不扩成新世界规则','同段空间神尊名乱码/异写、冬茗格中上位漂移，三千余撤兵/五万禁军等有口径差；不补未经解释的隐身或复活使算术圆整。','证据可验证的是字面不一致；原因可能误写/统计范围变化，应把修辞推断与事实区别。','检查通过只证明定位和结构，不证明每个解释成立；当前全部待主审。',[1251,1253,1262,1264,1324,1325,1340,1384])

CHARACTERS=[];SCENES=[];PATTERNS=[]
def character(key,title,summary,goal,constraint,relations,decisions,change,chapters,identity=''):
    card=dict(asset_type='character',scope='source-analysis',title=title,origin_key=P+'character/'+key,tags=['作者:失落叶','作品:斩龙','卷:6'],content=dict(summary=summary,goals=goal,constraints=constraint,relationship_directions=relations,key_decisions=decisions,stage_change=change,identity_notes=identity),evidence=ev(chapters),user_notes='',favorite=False,review_status='draft')
    CHARACTERS.append(card);return card
def scene(key,title,order,arc,goal,obstacle,choice,consequence,why,chapters,characters=(),status='resolved',knowledge=()):
    summary=consequence
    card=dict(asset_type='scene',scope='source-analysis',title=title,origin_key=P+'scene/'+key,tags=['作者:失落叶','作品:斩龙','卷:6'],content=dict(summary=summary,goal=goal,obstacle=obstacle,choice=choice,consequence=consequence,state_change=consequence,why_it_works=why,applicability='需要让选择改变后续资源/知情/关系的长篇节点。',failure_mode='照抄人名道具或把局部成功写成全局零代价。',narrative_order=order,arc=arc,stage_status=status),evidence=ev(chapters),user_notes='',favorite=False,review_status='draft')
    SCENES.append((key,card,characters,knowledge));return card
def pattern(key,title,summary,steps,conditions,failure,transform,scenes,chapters):
    PATTERNS.append(dict(asset_type='pattern',scope='reusable-pattern',title=title,origin_key=P+'pattern/'+key,tags=['作者:失落叶','作品:斩龙','卷:6'],content=dict(summary=summary,causal_steps=steps,applicability=conditions,failure_mode=failure,originality_transform=transform,derived_from_origin_keys=[P+'scene/'+x for x in scenes]),evidence=ev(chapters,'synthesis'),user_notes='',favorite=False,review_status='draft'))

